package world.gregs.voidps.cache.definition.data

import world.gregs.voidps.cache.Definition

/**
 * One texture of index 9: a procedural operation graph, not a raster.
 *
 * A texture is generated by evaluating [operations] - see
 * [world.gregs.voidps.cache.definition.TextureOpFormat] for the wire format - and reading three of
 * them out: [opaque] gives the colour, [opacity] the alpha and [hdr] the intensity. Materials
 * (index 26) are one to one with textures and say how the result is used.
 *
 * [trailer] is the honest residual. 2,562 of the 727 cache's 2,591 textures carry ten more bytes
 * after the three output indices, and this revision's client reads none of them: it stops at the
 * third index. The remaining 29 - ids 2562 to 2590, the newest in the cache and the same 29 whose
 * graphics carry an explicit palette entry 0 - carry no trailer at all, so it is not even a fixed
 * part of the format. It is kept verbatim as hex rather than guessed at.
 */
data class TextureDefinition(
    override var id: Int = -1,
    var operations: List<TextureOp> = emptyList(),
    /** The operation whose colour output is the texture. */
    var opaque: Int = 0,
    /** The operation whose output is the alpha channel. */
    var opacity: Int = 0,
    /** The operation whose output is the hdr intensity. */
    var hdr: Int = 0,
    /** Bytes past the three output indices that the client never reads, as lower case hex. */
    var trailer: String? = null
) : Definition
